INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6604518, 984357, 46918, '<td valign="top">I think you deserve this as your 1st ribbon. If you were here I would definitely buy you the 1st round of drinks.</td>', 'I think you deserve this as your 1st ribbon. If you were here I would definitely buy you the 1st round of drinks.', '2011-11-27 17:59:05.000000', NULL, 0),
(6604791, 984319, 100831, '<td valign="top">This has soul. Wonderful image.</td>', 'This has soul. Wonderful image.', '2011-11-28 00:34:02.000000', NULL, 0),
(6605150, 984514, 131284, '<td valign="top">My favourite image of this challenge (I gave it an 8). I find it a shame (although in retrospect somewhat predictable) that it finished so low and with a score of &lt;5. Despite being abstract this (imo) fits the challenge much better than the majority of the highest scoring entries that while perhaps ''good'' images, I found somewhat soulless (or in some cases, missing the point). This entry, for me, really conveys emotion which I think is the most important factor and a real tribute to all those who''ve lost their lives in war.<br/> <br/>I''m glad you''re never perturbed by the threat of low scores when entering abstracts like this Don, I won''t pretend to ''get'' all your entries, but whenever you come up with one such as this I find it hard to understand how it can be so underappreciated by the voters. I guess that''s art =).</td>', 'My favourite image of this challenge (I gave it an 8). I find it a shame (although in retrospect somewhat predictable) that it finished so low and with a score of <5. Despite being abstract this (imo) fits the challenge much better than the majority of the highest scoring entries that while perhaps ''good'' images, I found somewhat soulless (or in some cases, missing the point). This entry, for me, really conveys emotion which I think is the most important factor and a real tribute to all those who''ve lost their lives in war. I''m glad you''re never perturbed by the threat of low scores when entering abstracts like this Don, I won''t pretend to ''get'' all your entries, but whenever you come up with one such as this I find it hard to understand how it can be so underappreciated by the voters. I guess that''s art =).', '2011-11-28 10:28:43.000000', NULL, 0),
(6606312, 984540, 8891, '<td valign="top">WTG, Karma! Big congrats on your yellow!</td>', 'WTG, Karma! Big congrats on your yellow!', '2011-11-30 08:18:37.000000', NULL, 0),
(6606330, 984357, 98022, '<td valign="top">Powerful and moving image! Congrats on the extremely well deserved blue!</td>', 'Powerful and moving image! Congrats on the extremely well deserved blue!', '2011-11-30 08:49:58.000000', NULL, 0),
(6606639, 984357, 4793, '<td valign="top">Wonderful shot, congratulations</td>', 'Wonderful shot, congratulations', '2011-11-30 16:47:18.000000', NULL, 0),
(6606644, 984479, 4793, '<td valign="top">Wonderful shot, congratulations.</td>', 'Wonderful shot, congratulations.', '2011-11-30 16:48:29.000000', NULL, 0),
(6606645, 984540, 4793, '<td valign="top">Nice shot, congrats!</td>', 'Nice shot, congrats!', '2011-11-30 16:49:18.000000', NULL, 0),
(6606744, 984540, 63244, '<td valign="top">Well deserved! The colors and the composition are excellent! Congrats!</td>', 'Well deserved! The colors and the composition are excellent! Congrats!', '2011-11-30 18:45:39.000000', NULL, 0),
(6606748, 984271, 63244, '<td valign="top">Beautiful!!!</td>', 'Beautiful!!!', '2011-11-30 18:48:45.000000', NULL, 0),
